// Standalone fallback: resolve client_config from the Notion registry by client_id.
// The n8n Notion node flattens properties as 'property_<snake_cased_name>'; prop() tolerates both.
const trigger = $('Execute Workflow Trigger').first().json;
const wantId = trigger.client_id;
const rows = $input.all();
function prop(props, name){ const keys=[name,'property_'+name,'property_'+String(name).toLowerCase().replace(/ /g,'_')]; let p; for(const k of keys){ const v=props&&props[k]; if(v!==undefined&&v!==null){ p=v; break; } } if(p===undefined||p===null) return null; if(typeof p==='string') return p; return p.value ?? p.name ?? p.email ?? p.checkbox ?? p.text ?? p ?? null; }
let match=null;
for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'client_id')===wantId){ match=props; break; } }
if(!match) throw new Error(`No client registry row found for client_id='${wantId}'`);
const client_config = {
  client_id: wantId,
  client_name: prop(match,'Client Name'),
  reference_docs_folder_id: prop(match,'reference_docs_folder_id')
};
return [{ json: { client_id: wantId, client_config, data: trigger.data, status: 'ok', errors: [] } }];

// Concatenate the extracted text of the client's reference docs into one grounding block.
// The old caps (1500 chars/doc, 6000 total) allowed about a thousand words of evidence to
// ground a document that should run to eight thousand. Raised, and split per agent in
// 'Plan Chapters'. grounded_on records provenance for traceability.
const items = $input.all();
const parts = [];
const names = [];
for (const it of items) {
  const t = it.json.text || it.json.data || '';
  if (t) parts.push(String(t).slice(0, 6000));
  if (it.json.name) names.push(it.json.name);
}
const grounding = parts.join('\n\n---\n\n').slice(0, 24000);
return [{ json: { grounding, grounded_on: names } }];

// Turn the resolved chapter list into a per-agent brief.
//
// One agent per chapter would be 14+ calls with tone drift and a bill to match; one agent for
// everything is what we had, and it could not fit a 20-page document into a single reply. Briefs
// are grouped by DISCIPLINE instead: each agent gets a coherent slice, its own token budget and
// its own voice.
const cfg = $json.proposal_config || {};
const grounding = $json.grounding || '';
const trig = $('Execute Workflow Trigger').first().json;
const rfq = (trig.data && trig.data.rfq) || trig.data || {};

const briefs = { A1: [], A2: [], A3: [] };
const tablesByAgent = { A1: [], A2: [], A3: [] };
const boilerplate = [];

const push = (entry, parentTitle) => {
  const agent = entry.agent;
  const item = {
    id: entry.id,
    title: entry.title,
    numero: entry.numero,
    parent: parentTitle || null,
    guidance: entry.guidance || '',
    tables: entry.tables || [],
  };
  if (agent && briefs[agent]) {
    briefs[agent].push(item);
    for (const t of item.tables) if (!tablesByAgent[agent].includes(t)) tablesByAgent[agent].push(t);
  } else if (entry.content_type === 'boilerplate' || entry.content_type === 'calculated') {
    // Not written by a model at all. Listed so the QA reviewer knows the chapter exists.
    boilerplate.push(item.id);
  }
};

for (const ch of cfg.chapters || []) {
  push(ch, null);
  for (const s of ch.sections || []) push(s, ch.title);
}

// Writing rules from the client's Drive sheet, rendered as prompt lines. Empty when the client
// has no sheet — the agents then fall back to their own house style.
const r = cfg.rules || {};
const ruleLines = [];
if (r.tone) ruleLines.push(`Tone: ${r.tone}`);
if (r.person) ruleLines.push(`Voice: ${r.person}`);
if (r.units) ruleLines.push(`Units: ${r.units}`);
if (r.date_format) ruleLines.push(`Date format: ${r.date_format}`);
if (Array.isArray(r.forbidden_words) && r.forbidden_words.length) ruleLines.push(`NEVER use these words: ${r.forbidden_words.join(', ')}`);
if (Array.isArray(r.must_mention) && r.must_mention.length) ruleLines.push(`Work these points in where relevant: ${r.must_mention.join(', ')}`);
for (const [from, to] of Object.entries(r.terminology || {})) ruleLines.push(`Say "${to}" rather than "${from}"`);
const rules_text = ruleLines.length ? ruleLines.join('\n') : '(no client-specific writing rules configured)';

// Column definitions for the tables each agent owns, so it returns rows the template can render
// rather than prose that looks like a table.
const cols = cfg.table_columns || {};
const tableSpec = (agent) => {
  const wanted = tablesByAgent[agent];
  if (!wanted.length) return '(this agent owns no tables)';
  return wanted.map((t) => `${t}: [${(cols[t] || []).join(', ')}]`).join('\n');
};

const language = cfg.language || rfq.language || 'en';
const langName = language === 'es' ? 'Spanish (español)' : 'English';

return [{ json: {
  client_id: trig.client_id,
  language,
  langName,
  tier: cfg.tier || 'B',
  rules_text,
  briefs,
  boilerplate_sections: boilerplate,
  tables_A1: tableSpec('A1'),
  tables_A2: tableSpec('A2'),
  tables_A3: tableSpec('A3'),
  // A1 and A2 need the technical detail; A3 needs voice and structure more than specifics, so it
  // gets the opening slice rather than the whole block.
  grounding_full: grounding || '(no reference material available; write conservatively)',
  grounding_tone: (grounding || '').slice(0, 8000) || '(no reference material available)',
  rfq: rfq,
  proposal_config: cfg,
} }];

