// Merge the three agents' output into one draft, keyed by render key.
//
// Boilerplate is deliberately NOT merged here. Clause text goes straight from the client's Drive
// sheet into the render context (modules/proposal/render_context.js), so there is exactly one
// path from the spreadsheet to the paper and no model sits on it. The QA agent sees the clauses
// as read-only context.
const plan = $('Plan Chapters').first().json;

const collect = (nodeName) => {
  let out;
  try { out = $(nodeName).first().json.output; } catch (e) { return { sections: {}, tables: {} }; }
  out = out || {};
  return { sections: out.sections || {}, tables: out.tables || {} };
};

const parts = [collect('A1 — Technical Solution'), collect('A2 — Execution & Risk'), collect('A3 — Executive & Commercial')];

// Only keys the plan actually asked for survive. A model that invents a chapter id would
// otherwise put text somewhere the template has no block for, and it would vanish silently.
const allowed = new Set();
for (const list of Object.values(plan.briefs || {})) for (const b of list) allowed.add(b.id);
const allowedTables = new Set();
for (const list of Object.values(plan.briefs || {})) for (const b of list) for (const t of b.tables || []) allowedTables.add(t);

const sections = {};
const tables = {};
const rejected = [];

for (const part of parts) {
  for (const [k, v] of Object.entries(part.sections)) {
    const text = (v == null ? '' : String(v)).trim();
    if (!text) continue;
    if (!allowed.has(k)) { rejected.push(k); continue; }
    sections[k] = sections[k] ? `${sections[k]}\n\n${text}` : text;
  }
  for (const [k, rows] of Object.entries(part.tables)) {
    if (!Array.isArray(rows) || !rows.length) continue;
    if (!allowedTables.has(k)) { rejected.push(k); continue; }
    tables[k] = (tables[k] || []).concat(rows);
  }
}

return [{ json: {
  client_id: plan.client_id,
  language: plan.language,
  sections,
  tables,
  rejected_keys: rejected,
  proposal_config: plan.proposal_config,
} }];

