// Apply the QA reviewer's patches and shape Module 2's output envelope.
//
// A4 may rewrite a generated section, but it may NOT touch a boilerplate one — those come from the
// client's clause library and must reach the document verbatim. A patch aimed at one is downgraded
// to a finding so a human sees it instead.
const draft = $('Assemble Draft').first().json;
const plan = $('Plan Chapters').first().json;
const trig = $('Execute Workflow Trigger').first().json;

let review = {};
try { review = $input.first().json.output || {}; } catch (e) { review = {}; }

const sections = { ...draft.sections };
const findings = Array.isArray(review.findings) ? review.findings : [];
const protectedKeys = new Set(plan.boilerplate_sections || []);

let patches_applied = 0;
for (const p of Array.isArray(review.patches) ? review.patches : []) {
  const key = p && p.section;
  const text = p && p.text ? String(p.text).trim() : '';
  if (!key || !text) continue;
  if (protectedKeys.has(key)) {
    findings.push({ severity: 'warning', section: key, message: `QA tried to rewrite boilerplate section '${key}'; ignored. Contract text is edited in the client's Proposal Config sheet, not by an agent.` });
    continue;
  }
  if (!(key in sections)) continue;
  sections[key] = text;
  patches_applied += 1;
}

let grounded = [];
try { grounded = $('Aggregate Grounding').first().json.grounded_on || []; } catch (e) {}

const cfg = draft.proposal_config || {};
const blockers = findings.filter((f) => f && f.severity === 'blocker');

return [{ json: {
  client_id: trig.client_id,
  client_config: trig.client_config || null,
  proposal_config: cfg,
  status: 'ok',
  errors: [],
  data: {
    sections,
    tables: draft.tables,
    sections_generated: Object.keys(sections),
    agents_run: ['A5', 'A1', 'A2', 'A3', 'A4'],
    clauses_applied: (cfg.clauses || []).map((c) => c.id),
    qa: { reviewed: true, findings, patches_applied, blockers: blockers.length },
    grounded_on: grounded,
    config_warnings: cfg.warnings || [],
    rejected_keys: draft.rejected_keys || [],
  },
} }];
